const PROJECTS={
 speech:{id:'SYSTEM STUDY 001',title:'Perception at production scale.',subtitle:'A reference architecture for turning live video and audio into structured, observable information.',meta:['COMPUTER VISION','SPEECH AI','ARCHITECTURE EXPLORATION'],sections:[['The question','How do you preserve accuracy, identity context and responsiveness from camera and microphone input through to downstream applications? The hard part is not just inference, but end-to-end orchestration and bounded failure modes.'],['System boundary','Video frames and audio are captured, decoded and preprocessed; detectors, verifiers, VAD, ASR and diarization turn them into structured signals. Stage-level contracts define formats, input shapes, timestamps, retries, response shapes, and how errors propagate to clients.'],['What I would measure','Frames answered under sustained load, p50/p95 latency per stage, accuracy by slice (WER for speech; detection and verification error for vision), memory under concurrency, failures by input format, and user-visible correction burden.'],['Operating principle','Fix the layer where the problem lives: a fixed input shape can matter more than a new model. Keep model quality, serving reliability, and application-level usefulness as separate questions, and prove each with reproducible evidence.']],disclaimer:'Conceptual case study based on engineering domains; no confidential project data or verified customer outcomes are represented.'},
 eval:{id:'SYSTEM STUDY 002',title:'Evaluation as an engineering instrument.',subtitle:'A reference workflow that connects agent traces to interpretable quality decisions.',meta:['AI AGENTS','EVALUATION DESIGN','RELEASE READINESS'],sections:[['The question','How do you distinguish an agent that sounds convincing from one that repeatedly executes the correct process and produces supportable outcomes?'],['The system','Curated cases feed an instrumented agent run. Tool events, retrieval context, response artifacts, and evaluator outputs are tied together with run identifiers. Failure modes are labeled and compared across versions.'],['What I would measure','Final answer correctness, tool invocation and argument accuracy, groundedness, policy compliance, judge-human agreement, false pass rate, and slice-level reliability.'],['Release principle','Do not reduce quality to one composite score. Make the release recommendation reflect risk, confidence in the evaluation signal, and known coverage gaps.']],disclaimer:'Illustrative design pattern. This is not a claim of a completed benchmark or production release.'},
 knowledge:{id:'SYSTEM STUDY 003',title:'Knowledge with memory and provenance.',subtitle:'A reference platform for ingestion, verification, retrieval, and tool-based knowledge access.',meta:['KNOWLEDGE SYSTEMS','PROVENANCE','DATA ENGINEERING'],sections:[['The question','How can multiple applications consume knowledge while preserving source authority, freshness, and the ability to explain where a fact came from?'],['The architecture','Connectors and scheduled ingestion collect source data. Parsing and extraction produce versioned entities and documents. Quality checks, metadata, and provenance support both search and structured reasoning. APIs and tools expose bounded, auditable access.'],['What I would measure','Extraction validity, source coverage, update lag, stale-fact rate, citation correctness, retrieval effectiveness, and cost per verified update.'],['Design principle','A platform should support correction and audit. Search indices, graphs, and embeddings are implementation choices; trust is a property of the entire lifecycle.']],disclaimer:'Conceptual system study without proprietary implementation or undisclosed performance claims.'}
};
PROJECTS.perception={id:'SYSTEM STUDY 001',title:'Perception at production scale.',subtitle:'A reference architecture for turning live video and audio into structured, observable information.',meta:['COMPUTER VISION','SPEECH AI','PUBLIC-SAFE STUDY'],sections:[['The question','How do you keep accuracy, identity context and responsiveness from camera and microphone input all the way to the application? The hard part is not only inference, but end-to-end orchestration and bounded failure modes.'],['System boundary','Video frames and audio are captured, decoded and preprocessed. Face, pose and object detectors, verifiers, VAD, ASR and diarization turn them into structured signals. Stage contracts define formats, input shapes, timestamps, retries, response shapes and how errors propagate to clients.'],['What I would measure','Frames answered under sustained load, p50/p95 latency per stage, accuracy by slice (detection and verification error for vision, WER for speech), memory under concurrency, failures by input format and the correction burden on users.'],['Operating principle','Fix the layer where the problem lives. A fixed input shape can matter more than a new model, and a bug in the API layer can look like a model failure. Keep model quality, serving reliability and application usefulness as separate questions, and prove each with reproducible evidence.'],['Design boundary','This is a public-safe synthesis of technical concerns, not a disclosure of private data, deployment architecture, datasets or customer results.']],disclaimer:'Public-safe engineering study. No private client outcomes or confidential deployment details are presented.'};
PROJECTS.speech=Object.assign(PROJECTS.speech,{title:"Speech AI inside the clinical workflow.",subtitle:"An engineering study of speech as the first layer of human-centered clinical context.",meta:["HEALTHCARE AI", "SPEECH SYSTEMS", "PUBLIC-SAFE STUDY"],sections:[["Product context","A clinician needs an accurate record of what happened—not simply words produced by an ASR model. Capture conditions, interruptions, speaker roles, terminology, and downstream charting shape usefulness."],["Technical scope","Audio capture and decoding, noise handling, VAD, ASR, diarization, normalization, inference serving, and application contracts must fit together. Each handoff needs observable timing and clear failure behavior."],["Quality and economics","Track errors in medical entities, numbers and speaker attribution alongside latency percentiles, infrastructure capacity, operational effort and correction burden. A cheaper transcription is not a win when it creates costly human rework."],["Learning loop","Use domain review and real-workflow failure categories to update representative test slices. Keep model benchmarks, pipeline health and clinician usefulness distinguishable."],["Design boundary","This is a public-safe synthesis of technical concerns, not a disclosure of patient data, deployment architecture, private datasets or customer results."]],disclaimer:"Public-safe engineering study. No private client outcomes or confidential deployment details are presented."});
PROJECTS.eval=Object.assign(PROJECTS.eval,{title:"Agent reliability is an evidence discipline.",subtitle:"A system-level view of traceable reasoning, tool correctness and user-relevant evaluation.",meta:["AGENT SYSTEMS", "EVALUATION", "R&D TO PRODUCT"],sections:[["Product question","What matters is not whether an answer sounds convincing, but whether the agent uses legitimate evidence, follows bounded actions and helps a human complete an actual task."],["Architecture","Treat tool schemas, retrieval context, execution traces, outcome artifacts and evaluator decisions as related evidence. Stable run identifiers and failure taxonomies should support replay and explanation."],["Research vs delivery","An agent prototype is a hypothesis. Engineering readiness requires meaningful task coverage, human-calibrated judgments, reproducible regressions and documented risks."],["Cost of reliability","Measure token and tool budgets alongside accepted outcomes, retries, escalation to humans, and observability overhead. An additional verification step earns its place only when it reduces meaningful failures."],["Feedback path","Turn field failures into diagnosed causes, specific fixes and new regression cases—not an unstructured queue of complaints."]],disclaimer:"Public-safe engineering study. No private client outcomes or confidential deployment details are presented."});
PROJECTS.knowledge=Object.assign(PROJECTS.knowledge,{title:"Domain knowledge as maintained infrastructure.",subtitle:"An architecture for verified facts, provenance and tool-mediated access across products.",meta:["KNOWLEDGE PLATFORM", "HEALTHCARE & ENTERPRISE", "ARCHITECTURE"],sections:[["Product need","High-value assistants depend on domain knowledge that is current, explainable and usable in multiple workflows. A vector search index cannot establish authority on its own."],["Ingestion and lifecycle","Track sources, extraction versions, entity links, metadata, review status, invalidation and update cadence. Different facts require different authority and freshness rules."],["Serving interfaces","Choose full-text, structured queries, knowledge graphs, retrieval augmentation or deterministic tools based on the question. Avoid forcing every decision through a single generative mechanism."],["Economics and ownership","Price crawling, extraction, verification, indexing, updates and query serving. Establish domain ownership and auditable correction flows before scaling a shared platform."],["Feedback loop","Monitor retrieval misses, disputed facts, staleness and error correction. Make knowledge repair a normal product operation, not a one-off data cleanup."]],disclaimer:"Public-safe engineering study. No private client outcomes or confidential deployment details are presented."});
PROJECTS.his={
 id:'WORKFLOW CONTRACT / CONCEPTUAL STUDY',title:'Clinical assistance without silent authority.',subtitle:'A public-safe reference contract for building reliable AI-assisted documentation and hospital-system handoff.',
 meta:['HEALTHCARE PRODUCT','INTERFACES & PROVENANCE','DESIGN STUDY'],
 sections:[
  ['The actual product boundary','A clinical assistant can summarize and draft information but must not invent facts, identify an unverified patient or silently make a clinical decision. The product should help a clinician work faster while remaining accountable to clinical workflow and permissions.'],
  ['Source and responsibility','Trusted identity, encounter context, record access and persistence belong to the authorized application/integration layer. AI extracts and maps supported information from provided sources into a reviewable draft. Clinicians approve clinical decisions; authorized backend workflow persists the outcome.'],
  ['Field-level contract','A draft field carries its origin, source reference and version, confirmation state, relevant measurement time and unit, and an explicit missing/conflict behavior. Absence of evidence is not a negative clinical finding. Transcript speech is not automatically an authenticated observation.'],
  ['Failure and recovery','When source systems disagree, access is denied or evidence is missing, the system should surface the uncertainty instead of guessing. Authorization is rechecked at action time; drafts and approvals are distinct operations.'],
  ['Status and evidence','This is a generalized design study inspired by domain workflow requirements, not a claim that a specific customer integration, release or clinical outcome has been validated.']
 ],disclaimer:'Conceptual design. No patient data, private contract details or claims of deployed clinical outcomes are included.'
};

