function showDrawer(kind,item){preOverlayFocus=document.activeElement;activeItem={kind,item};document.body.classList.add('lock');overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');document.getElementById('drawerId').textContent='SYSTEM STUDY / ARCHITECTURE';drawer.scrollTop=0;document.getElementById('readProgress').style.width='0%';const lead=item.id;const meta=item.meta;drawerBody.innerHTML=`<div class="drawer-kicker">${lead}</div><h2>${item.title}</h2><p class="drawer-subtitle">${item.subtitle}</p><div class="drawer-rule"></div><div class="drawer-meta">${meta.map(v=>'<span>'+v+'</span>').join('')}</div>${sectionHtml(item.sections)}<div class="drawer-copy aside-note">${item.disclaimer}</div><div class="drawer-actions"><button id="copyLink">COPY LINK &nearr;</button><button id="closeLink">BACK TO PORTFOLIO &times;</button></div>`;document.getElementById('copyLink').addEventListener('click',()=>{const url=location.href;copyToClipboard(url).then(()=>{const b=document.getElementById('copyLink');if(b)b.textContent='LINK COPIED'}).catch(()=>{const b=document.getElementById('copyLink');if(b)b.textContent='COPY URL FROM ADDRESS BAR'})});document.getElementById('closeLink').addEventListener('click',closeDrawer);document.getElementById('closeDrawer').focus({preventScroll:true})}
