 const vs=`attribute vec3 aPosition;attribute vec3 aNormal;uniform mat4 uProjection;uniform float uYaw;uniform float uPitch;uniform float uZoom;varying vec3 vNormal;varying vec3 vPosition;void main(){vec3 p=aPosition;vec3 n=aNormal;float cx=cos(uPitch),sx=sin(uPitch);p=vec3(p.x,p.y*cx-p.z*sx,p.y*sx+p.z*cx);n=vec3(n.x,n.y*cx-n.z*sx,n.y*sx+n.z*cx);float cy=cos(uYaw),sy=sin(uYaw);p=vec3(p.x*cy+p.z*sy,p.y,-p.x*sy+p.z*cy);n=vec3(n.x*cy+n.z*sy,n.y,-n.x*sy+n.z*cy);p.z-=uZoom;vPosition=p;vNormal=normalize(n);gl_Position=uProjection*vec4(p,1.0);}`;
