 const gtm=[
 {code:'01 / FIND THE REAL JOB',sig:'?',title:'What hurts enough to change behavior?',body:'A model demo may impress while the actual workflow remains untouched. Observe the task, current workaround and cost of doing nothing.',evidence:'A specific user problem with observable frequency and consequences.'},
 {code:'02 / IDENTIFY THE DECISION CHAIN',sig:'↗',title:'Who buys, who uses, and who can say no?',body:'Enterprise and healthcare adoption involves the economic buyer, daily operator, IT/security gatekeepers and domain decision-makers. Their incentives are different.',evidence:'Mapped stakeholders, budget authority, approval path and an actual champion.'},
 {code:'03 / VALIDATE ONE WORKFLOW',sig:'1',title:'Can one narrow pilot earn repeat use?',body:'Keep scope deliberate. Observe the workflow with the right users, test trust and integration constraints, and learn whether the system is worth changing habits for.',evidence:'Representative use, accepted outcomes and explicit user corrections.'},
 {code:'04 / OBSERVE BEHAVIOR',sig:'∞',title:'Is the product becoming a habit?',body:'Trial is not adoption. Study repeat task completion, human oversight, support burden, willingness to recommend and workflows the product actually replaces.',evidence:'Repeated useful completion with acceptable time, reliability and total cost.'},
 {code:'05 / EARN EXPANSION',sig:'+',title:'Can value survive distribution and scale?',body:'A successful pilot still needs deployment, onboarding, procurement, safety approval, operating support and credible economics to become a repeatable business.',evidence:'Evidence for continuing, expanding, charging or deliberately stopping.'}
 ];
 function applyGtm(index){const d=gtm[index];if(!d)return;const b=document.querySelector(`[data-gtm="${index}"]`);choose('[data-gtm]',b);textValues({v4GtmIndex:d.code,v4GtmSig:d.sig,v4GtmTitle:d.title,v4GtmBody:d.body,v4GtmEvidence:d.evidence})}
 document.querySelectorAll('[data-gtm]').forEach(b=>b.addEventListener('click',()=>applyGtm(Number(b.dataset.gtm))));
 const decisions={
 differentiated:{label:'BUILD SELECTIVELY',glyph:'↗',title:'Own the domain-specific advantage.',desc:'Build where workflow, authority, quality or proprietary domain understanding creates real differentiation. Reuse commodity infrastructure around it.',test:'Prove the differentiator in a narrow user workflow before platformizing it.'},
 commodity:{label:'BUY / REUSE',glyph:'↘',title:'Do not reinvent solved infrastructure.',desc:'Identity, generic monitoring, CI, common metadata and other non-differentiating services usually deserve an integration-first evaluation.',test:'Compare complete ownership cost, exit path, security and integration fit.'},
 unproven:{label:'DEFER / TEST',glyph:'⏸',title:'Do not build before demand is understood.',desc:'A speculative feature is a liability when there is no credible owner, workflow, user signal or path to meaningful validation.',test:'Find the smallest prototype, customer test or operational experiment that could change the decision.'},
 integration:{label:'ADAPT / COMPOSE',glyph:'↔',title:'Own the seam, not the whole stack.',desc:'Extend mature components through narrow, explicit contracts. A cohesive interface can provide leverage without creating a new platform to maintain.',test:'Demonstrate the missing capability, compatibility, maintenance cost and rollback path.'}
 };
